<?php
if(!defined('ABSPATH'))exit;
final class Scrolly_Locator_Resource {
 static function e($s){return esc_html((string)$s);}
 static function field($label,$help='',$value=''){return '<section class="answer"><label>'.self::e($label).'</label>'.($help?'<p class="hint">'.self::e($help).'</p>':'').'<div class="write" role="textbox" aria-label="'.esc_attr($label).'" contenteditable="true">'.self::e($value).'</div></section>';}
 static function card($title,$text){return '<div class="card"><h3>'.self::e($title).'</h3><p>'.self::e($text).'</p></div>';}
 static function page($n,$title,$body,$resource){return '<section class="sheet"><header><b>SCROLLY</b><span>'.self::e($resource).' · '.$n.'/5</span></header><h2>'.self::e($title).'</h2>'.$body.'<footer>One offer. One useful move. · Resource '.Scrolly_Locator_Model::RESOURCE_VERSION.'</footer></section>';}
 static function render($p){
  $r=Scrolly_Locator_Model::result($p);$m=Scrolly_Locator_Model::module($p);$offer=$r['id']==='quiz-offer';$grow=$r['id']==='quiz-grow';$title=$r['title'];$channel=Scrolly_Locator_Model::channel($p);
  $revenue=['zero'=>'$0','under1k'=>'$1–$999','1kto10k'=>'$1,000–$9,999','10kplus'=>'$10,000 or more','unknown'=>'Not sure'][$p['revenue']];
  $others=array_values(array_diff($p['channels'],[$p['primary_channel']]));$other_names=array_map(fn($c)=>Scrolly_Locator_Model::CHANNELS[$c],$others);
  $paid=$p['paid']==='yes'?'You report paid promotion. Review the current offer, destination, spend and customer actions before adding spend. Profitability is not established.':($p['paid']==='past'?'You used paid promotion before but are not running ads now. This plan does not tell you to restart ads.':'No current paid promotion is reported. Use a focused existing or buyer-discovery route; no ad budget is assumed.');
  $summary='<div class="summary"><p><b>Your stated starting point</b><br>'.self::e($p['offer_text']).'</p><p><b>Reported last-30-day revenue</b><br>'.self::e($revenue).' · revenue before costs</p><p><b>Primary execution channel</b><br>'.self::e($channel).'</p><p><b>Your focus</b><br>'.self::e($m['focus']).'</p></div><p class="hint">Your description is visitor-provided context. Skill, demand and profitability have not been verified.</p>';
  $intro='<p class="eyebrow">YOUR PERSONALIZED ACTION KIT</p><h1>'.self::e($title).'</h1><p class="lead">'.self::e($offer?'Leave with an offer someone can understand, a reasoned starting price and one clear buying action.':($grow?'Run one focused commercial experiment and decide what deserves another round.':'Improve one point in your buying journey and make the next sale easier to repeat.')).'</p><h3>Your starting point</h3>'.$summary;
  if($offer){
   $intro.=self::card('1 / Choose a buyer and outcome','Choose one reachable type of buyer with a specific problem. A buyer hypothesis is a starting assumption, not proven demand.').self::field('Who is this for?','Name one buyer, their situation and the problem they would pay to resolve.').self::field('Your offer statement','I help [buyer] get [specific outcome] by delivering [deliverable] within [time].','Starting direction: '.$p['offer_text']);
   $page2=self::card('2 / Make the offer quotable','Use a small, specific deliverable. State what the customer receives before describing all your skills.').self::field('Deliverable and included scope','What exactly does the customer receive? Define quantity, format and included work.').self::field('Exclusions, inputs and revisions','What is not included? What must the customer provide? State any revision limit.').self::field('Delivery expectation and buying action','When will it be delivered? Where can the customer buy or ask a relevant question?').'<h3>3 / Set a reasoned starting price</h3><p>Estimate delivery time × a planning rate, then add direct costs. Compare genuinely similar scoped offers and check whether the price makes the work viable. A cost floor is not evidence of willingness to pay. For a reusable product, distinguish development costs from per-sale costs; do not assume every buyer funds all development time.</p>'.self::card('Example only — not your recommended price','A service taking 2 hours at a $25 planning rate, with $10 direct costs, has a $60 planning cost floor. Compare the scope and market before choosing a price. Your figures may be entirely different.').self::field('Your estimate and comparison','Delivery hours × planning rate + direct costs; two comparable scoped offers; your reasoned starting price.');
  }else{
   $intro.=self::card('1 / Choose the offer you will work on','Use one offer with actual purchases. Record the relevant buying/contact route and keep the rest of the business steady.').self::field('Selected offer and intended buyer','Use your stated offer as a starting point; narrow it if needed.',$p['offer_text']).self::field('Current buying path','Where does a suitable buyer see the offer, ask a question and purchase?');
   $page2=self::card('2 / Check the reported bottleneck',$m['focus']).'<ol class="steps">'.implode('',array_map(fn($x)=>'<li>'.self::e($x).'</li>',$m['steps'])).'</ol><h3>Your quick current-state check</h3>'.self::field('What happens now?','Use recent examples. Record the actual point where buyers stop or the repeat need that goes unmet.').self::field('One baseline','Record a count and time period: visits, qualified questions, purchases or eligible returning customers. Include the denominator where available.').self::field('What will you change?','Change one element. Avoid changing audience, offer, price and page at the same time.',$m['change']).self::field($grow?'Your hypothesis':'Your expected improvement','If I change [one thing], I expect [buyer action] because [reason]. This is an expectation to examine, not a guarantee.').self::field('Primary measure and guardrail',$m['measure'].' Keep an eye on margin, delivery capacity and customer experience.');
  }
  $page3=self::card($offer?'4 / Work on your chosen priority':'3 / Execute on one primary channel',$m['focus']).'<p>'.self::e($m['change']).'</p><h3>'.self::e($channel).'</h3><p>'.self::e(Scrolly_Locator_Model::channel_action($p)).'</p>'.self::field($p['primary_channel']==='none'?'Choose one buyer-discovery route':'Your primary-channel action','Use one action and one buying/contact destination. No separate plan for every platform.').($other_names?'<p class="hint">Other channels you selected: '.self::e(implode(', ',$other_names)).'. They are context only; do not add tasks on them during this plan.</p>':'').'<h3>Paid / organic context</h3><p>'.self::e($paid).'</p>';
  if($p['paid']==='yes'){$adnames=['meta'=>'Meta / Facebook / Instagram','google'=>'Google / YouTube','tiktok'=>'TikTok','pinterest'=>'Pinterest','other'=>'Another platform'];$page3.='<p class="hint">Reported paid platforms: '.self::e(implode(', ',array_map(fn($x)=>$adnames[$x],$p['ad_platforms']))).'. This does not create another execution channel.</p>';}
  if($p['priority']==='repeat')$message='Example only: “You previously bought [item/service]. If [relevant repeat need] is useful now, here is [clear next offer/action]. No pressure if it is not a fit.” Only contact customers through a permitted route.';
  elseif($p['priority']==='messages')$message='Example only: “For [need], the offer includes [scope], takes [timing] and costs [price]. Here is [relevant proof/answer]. If it fits, the next step is [buy/contact action].” Respond to the actual question; avoid pressure.';
  else $message='Example only: “I help [buyer] with [problem] by delivering [specific thing]. Here is [real example]. If you need this, [one buying/contact action].” Use truthful proof and the rules of your chosen channel.';
  $page3.=self::card('A customer-facing starting point',$message).self::field('Write your version','Use your actual buyer, deliverable and next action. Do not invent testimonials or guaranteed outcomes.').self::field('Before sharing','Check the link/contact action on a phone. Make scope and delivery clear. For existing ads, inspect the current destination before changing spend.');
  $days=$offer?['Choose one buyer and write the offer statement.','Define scope, exclusions, inputs and delivery.','Estimate costs, compare scoped offers and set a starting price.','Prepare one truthful sample or demonstration and the buying action.','Share through the primary channel with a small relevant audience.','Answer real questions; follow up respectfully where permitted.','Review what buyers understood and what needs to change.']:['Record the selected offer, current path and baseline.','Inspect the chosen bottleneck using recent evidence.','Prepare the one change and check the buying/contact action.','Run the change on the primary channel; keep other variables steady.','Record qualified actions, questions, purchases and practical costs.','Continue the same change; follow up only where appropriate.','Review the evidence and decide repeat, extend, adjust or stop.'];
  $page4='<p>A sequence you can spread over seven days. Fit it around your business; do not rush buyer decisions to meet a calendar.</p><div class="day-list">';foreach($days as $i=>$task)$page4.='<div class="day"><b>DAY '.($i+1).'</b><p>'.self::e($task).'</p></div>';$page4.='</div>'.self::field('Your commitment','Name the one offer, one primary channel and the next action you will actually complete.').'<p class="hint">Low-volume sales, referrals and search activity may need longer observation. Seven days does not establish statistical significance or guarantee a sale.</p>';
  $page5='<h3>Evidence, not just activity</h3><p>Record relevant buyer actions on your primary channel. Counts of views or followers alone do not establish sales or demand.</p><div class="evidence"><b>Action / date</b><b>Buyer response or result</b><b>Next decision</b>';for($i=1;$i<=3;$i++)foreach(['Action / date','Buyer response or result','Next decision'] as $label)$page5.='<div class="write small" role="textbox" aria-label="'.esc_attr($label.' '.$i).'" contenteditable="true"></div>';$page5.='</div>'.self::field('Actual numbers and practical costs','Record qualified visits/replies, buying questions, purchases, revenue, direct costs and delivery time. Separate observed facts from assumptions.').'<h3>Your review</h3>'.self::field('Keep / repeat','What produced useful buyer evidence and is practical to maintain?').self::field('Change / extend / stop','What should change? If the sample is small, what observation would make the next decision clearer?');
  $bridge=$r['club']==='10'?'Your future Scrolly fit is the $10K level. It is not currently available. Keep working on this useful experiment; a quiz recommendation is not a waitlist signup.':($r['club']==='unknown'?'Your revenue is unknown, so no income band has been assigned. The $1K Club may fit offer and customer-acquisition work; review its scope before deciding.':'Want a structured next step for your offer and customer-acquisition plan? Explore the $1K Club when that support fits your needs.');
  $page5.='<aside class="bridge"><h3>Your Scrolly next step</h3><p>'.self::e($bridge).'</p><a href="'.esc_url(home_url($r['club']==='10'?'/10k-club/':'/1k-club/')).'">'.($r['club']==='10'?'Read about the future $10K level':'Explore the $1K Club').'</a></aside><p class="hint">No customer or earnings guarantees. This kit helps you make and review one practical move.</p>';
  $css=file_get_contents(__DIR__.'/locator-resource.css');$js=file_get_contents(__DIR__.'/locator-resource.js');
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).'</title><style>'.$css.'</style></head><body><div class="toolbar"><b>SCROLLY / YOUR WORKING PLAN</b><button type="button" id="print-plan">Print / Save completed plan as PDF</button><p>Edits stay in this open document and are not automatically saved. Print or save your completed plan as PDF before closing. Your answers in this kit are not sent to Scrolly.</p></div><main>'.self::page(1,'Your starting point',$intro,$title).self::page(2,$offer?'Make it a clear, quotable offer':'Choose one meaningful change',$page2,$title).self::page(3,'One channel. One action.',$page3,$title).self::page(4,'Your seven-day plan',$page4,$title).self::page(5,'Evidence and your next decision',$page5,$title).'</main><script>'.$js.'</script></body></html>';
 }
}
